import React from 'react';
import {AbsoluteFill,interpolateColors} from 'remotion';
import {useS,T,en,DUR,Easing,interpolate,clamp,FONT,Destello,sacudida} from './kit';
// VARIADO 2026-11-29 15:00 · "Nadie oye la voz que tú oyes" · 2.5D (docs/ESTILO_25D.md).
// Herramientas copiadas de docs/referencia_25D_Escena.tsx (Defs, Vol, Brillo2, caps, Bokeh, capas); los dibujos son nuevos.
// Colores fijos: aire = cian #19E0FF, hueso = naranja-dorado #FFB21F, celular = verde.
export const SUBS={arriba:1330,size:84,acento:'#C6FF00'};
const A=[0,7,16,25,41,56,66,75,89,97,107,118,137].map(T);
const L='#C6FF00',CY='#19E0FF',OR='#FFB21F',GR='#3BE87A';
type P=[string,string,string];type Pt=[number,number];
const q=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:Easing.inOut(Easing.cubic)});
const ea=(w:string,n=1)=>en(w,n)-.2; // la imagen entra 6 cuadros antes de su palabra
const ell=(cx:number,cy:number,rx:number,ry:number)=>`M${cx-rx} ${cy}a${rx} ${ry} 0 1 0 ${2*rx} 0a${rx} ${ry} 0 1 0 ${-2*rx} 0Z`;
const caps=(x1:number,y1:number,x2:number,y2:number,w:number)=>{const a=Math.atan2(y2-y1,x2-x1),r=w/2,nx=-Math.sin(a)*r,ny=Math.cos(a)*r;
 return `M${x1+nx} ${y1+ny}L${x2+nx} ${y2+ny}A${r} ${r} 0 0 0 ${x2-nx} ${y2-ny}L${x1-nx} ${y1-ny}A${r} ${r} 0 0 0 ${x1+nx} ${y1+ny}Z`;};
const SK:P=['#f7d3ac','#d99a62','#8e5128'],HK:P=['#5a5675','#1c1730','#06030d'],BLU:P=['#8fb0ff','#2355FF','#0b1f80'];
const IV:P=['#fffdf2','#f1e3c2','#b79d6c'],PNK:P=['#ffd6e0','#ff8fa8','#a02a50'],TQ:P=['#c8fff4','#19d9c0','#067a74'],GLD:P=['#fff2b0','#ffc83d','#a8700a'];
const Vol:React.FC<{id:string;d:string;c:P;sw?:number;o?:number;borde?:string}>=({id,d,c,sw=70,o=24,borde})=><g>
 <defs><clipPath id={id}><path d={d}/></clipPath></defs>
 <path d={d} fill={c[1]}/>
 <g clipPath={`url(#${id})`}>
  <path d={d} fill='none' stroke={c[2]} strokeWidth={sw} filter='url(#b18)' transform={`translate(${-o} ${-o})`}/>
  <path d={d} fill='none' stroke={c[0]} strokeWidth={sw*.75} filter='url(#b18)' transform={`translate(${o} ${o})`}/>
 </g>
 <path d={d} fill='none' stroke={borde||c[2]} strokeWidth={3} opacity={.55}/>
</g>;
const Brillo2:React.FC<{x:number;y:number;rx:number;ry:number;r?:number;o?:number}>=({x,y,rx,ry,r=-30,o=.75})=><ellipse cx={x} cy={y} rx={rx} ry={ry} transform={`rotate(${r} ${x} ${y})`} fill='#fff' opacity={o} filter='url(#b6)'/>;
const Defs:React.FC=()=><defs>
 <filter id='b6' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='6'/></filter>
 <filter id='b18' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='18'/></filter>
 <filter id='b40' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='40'/></filter>
 <radialGradient id='luz'><stop stopColor='#ffffff' stopOpacity='.5'/><stop offset='1' stopColor='#ffffff' stopOpacity='0'/></radialGradient>
 <linearGradient id='diente' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#ffffff'/><stop offset='1' stopColor='#d8d0c0'/></linearGradient>
</defs>;
// ---------- piezas de movimiento ----------
const Camino=(pts:Pt[],u:number)=>{const ls=pts.slice(1).map((p,i)=>Math.hypot(p[0]-pts[i][0],p[1]-pts[i][1])),tot=ls.reduce((a,b)=>a+b,0)||1;let f=Math.max(0,Math.min(1,u))*tot;
 for(let i=0;i<ls.length;i++){if(f<=ls[i]||i===ls.length-1){const k=ls[i]?Math.min(1,f/ls[i]):0,[ax,ay]=pts[i],[bx,by]=pts[i+1];return{x:ax+(bx-ax)*k,y:ay+(by-ay)*k,a:Math.atan2(by-ay,bx-ax)*180/Math.PI};}f-=ls[i];}
 return{x:pts[0][0],y:pts[0][1],a:0};};
const smooth=(p:Pt[])=>{let d=`M${p[0][0]} ${p[0][1]}`;for(let i=1;i<p.length-1;i++){d+=`Q${p[i][0]} ${p[i][1]} ${(p[i][0]+p[i+1][0])/2} ${(p[i][1]+p[i+1][1])/2}`;}const l=p[p.length-1];return d+`L${l[0]} ${l[1]}`;};
const Pulso:React.FC<{x:number;y:number;a:number;c:string;w?:number;r?:number;sp?:number;o?:number}>=({x,y,a,c,w=10,r=34,sp=55,o=1})=>{const t=sp*Math.PI/180;
 const d=`M${Math.cos(-t)*r} ${Math.sin(-t)*r}A${r} ${r} 0 0 1 ${Math.cos(t)*r} ${Math.sin(t)*r}`;
 return <g transform={`translate(${x} ${y}) rotate(${a})`} opacity={o}><path d={d} stroke={c} strokeWidth={w*2.4} fill='none' strokeLinecap='round' opacity={.45} filter='url(#b6)'/><path d={d} stroke={c} strokeWidth={w} fill='none' strokeLinecap='round'/><path d={d} stroke='#fff' strokeWidth={w*.35} fill='none' strokeLinecap='round' opacity={.75} transform='translate(-2 -2)'/></g>;};
const Tren:React.FC<{pts:Pt[];s:number;t0:number;col:(u:number)=>string;n?:number;dur?:number;w?:number;r?:number;sp?:number;fin?:number}>=({pts,s,t0,col,n=3,dur=1.1,w=10,r=34,sp=55,fin=1e9})=>{
 if(s<t0||s>fin)return null;
 return <>{Array.from({length:n}).map((_,j)=>{const u=((((s-t0)/dur)-j/n)%1+1)%1,{x,y,a}=Camino(pts,u),o=Math.min(1,u*10,(1-u)*6);return <Pulso key={j} x={x} y={y} a={a} c={col(u)} w={w} r={r} sp={sp} o={o}/>;})}</>;};
const Aire:React.FC<{pts:Pt[];s:number;t0:number;n?:number}>=({pts,s,t0,n=18})=>{if(s<t0)return null;
 return <>{Array.from({length:n}).map((_,j)=>{const u=(j/n+(s-t0)*.09)%1,{x,y,a}=Camino(pts,u),ar=a*Math.PI/180,tg=Math.sin(s*13-j*.9)*8,nm=Math.cos(s*9+j)*5,o=Math.min(1,u*8,(1-u)*8),
  px=x+Math.cos(ar)*tg-Math.sin(ar)*nm,py=y+Math.sin(ar)*tg+Math.cos(ar)*nm;
  return <g key={j} opacity={o}><circle cx={px+2} cy={py+3} r={8} fill='#003a5c' opacity={.4}/><circle cx={px} cy={py} r={8} fill={CY}/><circle cx={px-2.5} cy={py-3} r={3} fill='#fff'/></g>;})}</>;};
const Flecha:React.FC<{pts:Pt[];c:string;p:number;w?:number}>=({pts,c,p,w=16})=>{if(p<=.01)return null;const h=Camino(pts,p);
 return <g><path d={smooth(pts)} pathLength={1} strokeDasharray='1 1' strokeDashoffset={1-p} stroke={c} strokeWidth={w*2.2} fill='none' strokeLinecap='round' opacity={.4} filter='url(#b6)'/>
  <path d={smooth(pts)} pathLength={1} strokeDasharray='1 1' strokeDashoffset={1-p} stroke={c} strokeWidth={w} fill='none' strokeLinecap='round'/>
  <path d={smooth(pts)} pathLength={1} strokeDasharray='1 1' strokeDashoffset={1-p} stroke='#fff' strokeWidth={w*.3} fill='none' strokeLinecap='round' opacity={.7}/>
  <g transform={`translate(${h.x} ${h.y}) rotate(${h.a})`}><path d={`M${w*1.5} 0L${-w*.8} ${-w*1.5}L${-w*.8} ${w*1.5}Z`} fill={c} stroke='#fff' strokeWidth={3}/></g></g>;};
const pop=(s:number,t:number)=>{const u=Math.max(0,Math.min(1,(s-t)/.35));if(u<=0)return 0;const c1=1.70158,c3=c1+1;return 1+c3*Math.pow(u-1,3)+c1*Math.pow(u-1,2);};
const Rot:React.FC<{x:number;y:number;t:number;s:number;txt:string;c?:string;w?:number;sz?:number}>=({x,y,t,s,txt,c=L,w=300,sz=46})=>{const k=pop(s,t);if(k<=0)return null;
 return <g transform={`translate(${x} ${y}) scale(${k})`}><rect x={-w/2} y={-44} width={w} height={104} rx={26} fill='#000' opacity='.4' filter='url(#b6)'/><rect x={-w/2} y={-52} width={w} height={104} rx={26} fill='#14002a' stroke={c} strokeWidth={6}/><rect x={-w/2+8} y={-46} width={w-16} height={22} rx={11} fill='#fff' opacity='.1'/><text y={sz*.34} textAnchor='middle' fill={c} fontSize={sz} fontWeight={900} fontFamily={FONT}>{txt}</text></g>;};
const mm=(s:number,a=1)=>a*(.4+.6*Math.abs(Math.sin(s*15)));
const Ripple:React.FC<{x:number;y:number;s:number;t0:number;c:string;r?:number}>=({x,y,s,t0,c,r=70})=>{if(s<t0)return null;const u=((s-t0)%.7)/.7;return <circle cx={x} cy={y} r={10+u*r} fill='none' stroke={c} strokeWidth={8*(1-u)+2} opacity={(1-u)*.9}/>;};
// ---------- mano con volumen: palma, dedos (cápsulas), nudillos y uñas ----------
type F=[number,number];
const ABIERTA:F[]=[[-14,92],[-4,104],[6,100],[16,82]],SALUDO:F[]=[[-26,88],[-9,104],[9,100],[26,80]];
const INDICE:F[]=[[-3,100],[180,40],[180,42],[180,36]],PUNO:F[]=[[180,38],[180,40],[180,38],[180,32]];
const Mano:React.FC<{id:string;c?:P;dedos:F[];pulgar:F;x?:number;y?:number;rot?:number;k?:number;manga?:P;brazo?:number;nail?:string}>=({id,c=SK,dedos,pulgar,x=0,y=0,rot=0,k=1,manga,brazo=0,nail='#e0243a'})=>{
 const bx=[-33,-11,11,33],ws=[27,28,27,23];
 const tipo=(b:number,f:F):Pt=>{const a=f[0]*Math.PI/180;return[bx[b]+Math.sin(a)*f[1],-44-Math.cos(a)*f[1]];};
 const ta=pulgar[0]*Math.PI/180,th:Pt=[-44+Math.sin(ta)*pulgar[1],34-Math.cos(ta)*pulgar[1]];
 const alt=(f:F)=>Math.abs(f[0])>120;
 const uña=(tx:number,ty:number,ang:number,key:string)=><g key={key} transform={`translate(${tx} ${ty}) rotate(${ang})`}><ellipse cy={13} rx={9} ry={12} fill={nail} stroke='#8a0f20' strokeWidth={1.5}/><ellipse cx={-2.5} cy={9} rx={2.6} ry={4.5} fill='#fff' opacity={.7}/></g>;
 return <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${k})`}>
  {brazo>0&&<><Vol id={id+'a'} d={caps(0,60,0,60+brazo,84)} c={c} sw={34} o={10}/>{manga&&<Vol id={id+'m'} d={caps(0,125,0,60+brazo,116)} c={manga} sw={40} o={12}/>}</>}
  {dedos.map((f,b)=>alt(f)?null:<Vol key={b} id={id+'d'+b} d={caps(bx[b],-44,tipo(b,f)[0],tipo(b,f)[1],ws[b])} c={c} sw={16} o={5}/>)}
  <Vol id={id+'t'} d={caps(-44,34,th[0],th[1],31)} c={c} sw={18} o={5}/>
  <Vol id={id+'p'} d='M-52 -40Q-56 30 -30 78Q0 96 34 78Q58 30 52 -40Q0 -56 -52 -40Z' c={c} sw={50} o={14}/>
  {dedos.map((f,b)=>alt(f)?<Vol key={'c'+b} id={id+'c'+b} d={caps(bx[b],-36,bx[b],-36+f[1]*.62,ws[b]+2)} c={c} sw={14} o={4}/>:null)}
  {dedos.map((f,b)=><circle key={'k'+b} cx={bx[b]} cy={-38} r={7} fill={c[0]} opacity={.55}/>)}
  {dedos.map((f,b)=>alt(f)?null:uña(tipo(b,f)[0]-Math.sin(f[0]*Math.PI/180)*8,tipo(b,f)[1]+Math.cos(f[0]*Math.PI/180)*8,f[0]+180,'n'+b))}
  {uña(th[0]-Math.sin(ta)*8,th[1]+Math.cos(ta)*8,pulgar[0]+180,'nt')}
 </g>;};
// ---------- persona de frente: cabeza proporcionada, orejas, pelo con volumen, ojos con párpado, nariz, labios, cuello y ropa ----------
type PP={id:string;s:number;skin?:P;hair?:P;top?:P;estilo?:'lacio'|'corto'|'rojo'|'canas';gafas?:boolean;aretes?:boolean;auri?:boolean;delantal?:boolean;m?:number;sonrisa?:number;rubor?:number;cover?:number;plug?:number;look?:number;ceja?:number};
const wrist=(hx:number,hy:number,r:number):Pt=>[hx-60*Math.sin(r*Math.PI/180),hy+60*Math.cos(r*Math.PI/180)];
const Brazo:React.FC<{id:string;sh:Pt;el:Pt;wr:Pt;c:P;manga:P}>=({id,sh,el,wr,c,manga})=><g>
 <Vol id={id+'f'} d={caps(el[0],el[1],wr[0],wr[1],66)} c={c} sw={26} o={8}/>
 <Vol id={id+'u'} d={caps(sh[0],sh[1],el[0],el[1],92)} c={manga} sw={30} o={9}/>
 <path d={caps(sh[0],sh[1],el[0],el[1],92)} fill='none' stroke={manga[0]} strokeWidth={3} opacity={.5}/>
 <circle cx={el[0]} cy={el[1]} r={38} fill={manga[1]} opacity={.0}/>
</g>;
const MA={skin:SK,hair:HK,top:BLU,estilo:'lacio' as const,aretes:true,auri:true};
const Persona:React.FC<PP>=({id,s,skin=SK,hair=HK,top=BLU,estilo='lacio',gafas=false,aretes=false,auri=false,delantal=false,m=0,sonrisa=0,rubor=0,cover=0,plug=0,look=0,ceja=0})=>{
 const bl=(s%3.4)>3.28,cm=150,cyc=cm-sonrisa*9,oh=m*36,cl='mc'+id,sk=skin;
 const boca=`M-52 ${cyc}Q0 ${cm-8} 52 ${cyc}Q0 ${cm+14+oh} -52 ${cyc}Z`;
 return <g>
  <ellipse cy={655} rx={310} ry={52} fill='#000' opacity='.3' filter='url(#b40)'/>
  {estilo==='lacio'&&<Vol id={id+'hb'} d='M-224 -30C-244 -245 -112 -316 0 -316C112 -316 244 -245 224 -30C228 70 216 150 198 195L120 185L-120 185L-198 195C-216 150 -228 70 -224 -30Z' c={hair} sw={60} o={18}/>}
  {estilo==='canas'&&<Vol id={id+'bn'} d={ell(0,-292,80,68)} c={hair} sw={40} o={12}/>}
  {auri&&<path d='M-150 392C-170 262 -90 218 0 218C90 218 170 262 150 392' stroke='#2a1448' strokeWidth={28} fill='none' strokeLinecap='round'/>}
  <Vol id={id+'cu'} d='M-68 150L-80 340Q0 430 80 340L68 150Z' c={sk} sw={44} o={12}/>
  <path d='M-68 190Q0 250 68 190L68 150L-68 150Z' fill={sk[2]} opacity={.35} filter='url(#b6)'/>
  <Vol id={id+'to'} d='M-292 655C-288 430 -216 345 -80 322Q0 380 80 322C216 345 288 430 292 655Z' c={top} sw={110} o={30}/>
  <path d='M-80 322Q0 380 80 322' stroke={top[0]} strokeWidth={7} fill='none' opacity={.9}/>
  {delantal&&<><Vol id={id+'de'} d='M-120 392Q0 420 120 392L146 655H-146Z' c={['#fff3a0','#ffd23d','#b8860b']} sw={60} o={18}/><path d='M-60 352L-92 392M60 352L92 392' stroke='#ffd23d' strokeWidth={22} strokeLinecap='round'/><rect x={-48} y={500} width={96} height={64} rx={14} fill='#ffd23d' stroke='#b8860b' strokeWidth={4}/></>}
  {auri&&[-1,1].map(k=><g key={k} transform={`translate(${k*152} 418)`}><Vol id={id+'au'+k} d={ell(0,0,48,62)} c={['#ff9ad8','#ff3fa4','#7a0a5a']} sw={40} o={12}/><ellipse rx={30} ry={42} fill='#3a0a38'/><ellipse rx={30} ry={42} fill='none' stroke='#ff9ad8' strokeWidth={4}/><Brillo2 x={-22} y={-34} rx={14} ry={8}/></g>)}
  {[-1,1].map(k=><g key={k}><Vol id={id+'e'+k} d={ell(k*188,14,32,54)} c={sk} sw={26} o={8}/><path d={`M${k*186} -14Q${k*206} 14 ${k*186} 44`} stroke={sk[2]} strokeWidth={5} fill='none' opacity={.6}/>
   <ellipse cx={k*188} cy={14} rx={32} ry={54} fill='#ff4f6a' opacity={rubor*.5} filter='url(#b6)'/></g>)}
  {aretes&&[-1,1].map(k=><g key={k}><circle cx={k*192} cy={104} r={26} fill='none' stroke='#a8700a' strokeWidth={9}/><circle cx={k*192} cy={104} r={26} fill='none' stroke='#ffc83d' strokeWidth={6}/><circle cx={k*192-10} cy={92} r={5} fill='#fff' opacity={.85}/></g>)}
  <Vol id={id+'hd'} d='M0 -258C128 -258 190 -160 186 -38C182 82 122 208 0 248C-122 208 -182 82 -186 -38C-190 -160 -128 -258 0 -258Z' c={sk} sw={130} o={36}/>
  {[-1,1].map(k=><ellipse key={k} cx={k*98} cy={72} rx={52} ry={32} fill='#ff4f6a' opacity={.18+rubor*.5} filter='url(#b18)'/>)}
  <Brillo2 x={-70} y={-150} rx={46} ry={16} r={-20} o={.35}/>
  <path d='M-12 -30C-18 18 -46 52 -42 76C-30 96 -12 90 0 96C12 90 30 96 42 76C46 52 18 18 12 -30' fill={sk[1]} stroke={sk[2]} strokeWidth={3}/><path d='M7 -20C11 22 26 50 30 68' stroke={sk[0]} strokeWidth={6} fill='none' opacity={.85} strokeLinecap='round'/>
  {[-1,1].map(k=><ellipse key={k} cx={k*17} cy={82} rx={9} ry={5} fill='#5a2a1a'/>)}
  {[-1,1].map(k=><g key={k} transform={`translate(${k*72} -18)`}>
   <path d='M-36 2Q0 -26 36 2Q0 24 -36 2Z' fill='#fff' stroke='#8a5a40' strokeWidth={2}/>
