  <path d={`M-56 ${cyc}Q-28 ${cm-30} 0 ${cm-14}Q28 ${cm-30} 56 ${cyc}Q0 ${cm-9} -56 ${cyc}Z`} fill='#c7405c'/>
  <path d={`M-54 ${cyc}Q0 ${cm+8+oh} 54 ${cyc}Q0 ${cm+38+oh} -54 ${cyc}Z`} fill='#e0607a'/>
  <Brillo2 x={-12} y={cm+oh+18} rx={22} ry={5} r={-4} o={.8}/>
  {estilo==='lacio'&&<Vol id={id+'hf'} d='M-200 -46C-232 -232 -112 -300 4 -298C130 -298 234 -232 200 -46C196 -96 184 -120 170 -134Q90 -102 0 -108Q-90 -102 -170 -134C-184 -120 -192 -96 -200 -46Z' c={hair} sw={60} o={16}/>}
  {estilo==='corto'&&<Vol id={id+'hf'} d='M-196 -46C-214 -214 -100 -268 0 -268C110 -268 214 -214 196 -46C186 -112 150 -160 100 -172C40 -150 -50 -150 -100 -172C-150 -160 -186 -112 -196 -46Z' c={hair} sw={60} o={16}/>}
